require_once dirname(__DIR__).'/includes/functions.php';$admin=require_role('admin');$id=(int)($_GET['id']??$_POST['id']??0);$event=null;if($id){$s=db()->prepare('SELECT * FROM events WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Event not found.');}}
