  db()->prepare($sql)->execute([$data['title'],$data['description'],$data['category'],$data['venue'],$data['event_date'],$data['start_time'],$data['end_time'],$deadline,(int)$data['max_participants'],$poster,$data['status'],$id]);
  if($event['poster']&&$poster!==$event['poster']&&is_file(UPLOAD_DIR.'/'.basename($event['poster'])))unlink(UPLOAD_DIR.'/'.basename($event['poster']));
