  flash('success','Event updated and registered students have been notified about changes.');redirect('admin/events.php');
 }else{$deadline=date('Y-m-d H:i:s',strtotime($data['reg_deadline']));db()->prepare('INSERT INTO events (title,description,category,venue,event_date,start_time,end_time,reg_deadline,max_participants,poster,status,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$data['title'],$data['description'],$data['category'],$data['venue'],$data['event_date'],$data['start_time'],$data['end_time'],$deadline,(int)$data['max_participants'],$poster,$data['status'],$admin['id']]);flash('success','Event created.');redirect('admin/events.php');}
 }catch(Throwable $e){$error=$e->getMessage();}
}
